#include <torch/extension.h>
torch::Tensor batchnorm2d_forward(torch::Tensor x,
                                   torch::Tensor weight,
                                   torch::Tensor bias,
                                   torch::Tensor running_mean,
                                   torch::Tensor running_var,
                                   bool training,
                                   double momentum,
                                   double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// ---------------------------------------------------------------------
// Kernel 1: per-channel reduction of sum and sum-of-squares
// One CUDA block handles one channel; grid-stride loop over (N, HW).
// ---------------------------------------------------------------------
template <typename T>
__global__ void bn_reduce_kernel(
    const T* __restrict__ X,
    float* __restrict__ sum_out,
    float* __restrict__ sumsq_out,
    int N, int C, int64_t HW, int blocks_per_channel)
{
    int c = blockIdx.x / blocks_per_channel;
    int chunk = blockIdx.x % blocks_per_channel;
    int64_t CHW = (int64_t)C * HW;
    // View input as (N, C, HW) using CuTe tensor abstraction
    auto mX = make_tensor(make_gmem_ptr(X),
                           make_shape(N, C, HW),
                           make_stride(CHW, HW, Int<1>{}));
    int64_t count = (int64_t)N * HW;
    extern __shared__ float sdata[];
    float* s_sum   = sdata;
    float* s_sumsq = sdata + blockDim.x;
    float local_sum = 0.0f, local_sumsq = 0.0f;
    // Multiple blocks cooperate on the same channel to improve SM
    // utilization when C is smaller than the number of available SMs.
    int64_t start = (int64_t)chunk * blockDim.x + threadIdx.x;
    int64_t step  = (int64_t)blockDim.x * blocks_per_channel;
    for (int64_t i = start; i < count; i += step) {
        int64_t n  = i / HW;
        int64_t hw = i - n * HW;
        float v = (float)mX((int)n, c, hw);
        local_sum   += v;
        local_sumsq += v * v;
    }
    s_sum[threadIdx.x]   = local_sum;
    s_sumsq[threadIdx.x] = local_sumsq;
    __syncthreads();
    for (unsigned stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x]   += s_sum[threadIdx.x + stride];
            s_sumsq[threadIdx.x] += s_sumsq[threadIdx.x + stride];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        atomicAdd(&sum_out[c],   s_sum[0]);
        atomicAdd(&sumsq_out[c], s_sumsq[0]);
    }
}
// ---------------------------------------------------------------------
// Kernel 1b: vectorized (float4) per-channel reduction of sum and
// sum-of-squares. Valid when HW is a multiple of 4 and the input
// pointer is 16B aligned. Improves memory throughput via wide
// coalesced loads compared to the scalar reduction kernel above.
// ---------------------------------------------------------------------
__global__ void bn_reduce_kernel_vec4(
    const float4* __restrict__ X4,
    float* __restrict__ sum_out,
    float* __restrict__ sumsq_out,
    int N, int C, int64_t HW4, int64_t CHW4, int blocks_per_channel)
{
    int c = blockIdx.x / blocks_per_channel;
    int chunk = blockIdx.x % blocks_per_channel;
    // View input as (N, C, HW4) of float4 using CuTe tensor abstraction
    auto mX4 = make_tensor(make_gmem_ptr(X4),
                           make_shape(N, C, HW4),
                           make_stride(CHW4, HW4, Int<1>{}));
    int64_t count4 = (int64_t)N * HW4;
    extern __shared__ float sdata[];
    float* s_sum   = sdata;
    float* s_sumsq = sdata + blockDim.x;
    float local_sum = 0.0f, local_sumsq = 0.0f;
    // Multiple blocks cooperate on the same channel to improve SM
    // utilization when C is smaller than the number of available SMs.
    int64_t start = (int64_t)chunk * blockDim.x + threadIdx.x;
    int64_t step  = (int64_t)blockDim.x * blocks_per_channel;
    for (int64_t i = start; i < count4; i += step) {
        int64_t n   = i / HW4;
        int64_t hw4 = i - n * HW4;
        float4 v = mX4((int)n, c, hw4);
        local_sum   += v.x + v.y + v.z + v.w;
        local_sumsq += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
    }
    s_sum[threadIdx.x]   = local_sum;
    s_sumsq[threadIdx.x] = local_sumsq;
    __syncthreads();
    for (unsigned stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x]   += s_sum[threadIdx.x + stride];
            s_sumsq[threadIdx.x] += s_sumsq[threadIdx.x + stride];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        atomicAdd(&sum_out[c],   s_sum[0]);
        atomicAdd(&sumsq_out[c], s_sumsq[0]);
    }
}

// ---------------------------------------------------------------------
// Kernel 2: finalize mean / invstd, update running stats
// ---------------------------------------------------------------------
__global__ void bn_finalize_kernel(
    const float* __restrict__ sum,
    const float* __restrict__ sumsq,
    float* __restrict__ mean_out,
    float* __restrict__ invstd_out,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    int C, int64_t count, float eps, float momentum, bool training)
{
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= C) return;

    if (training) {
        float m   = sum[c] / (float)count;
        float var = sumsq[c] / (float)count - m * m;
        if (var < 0.0f) var = 0.0f;

        mean_out[c]   = m;
        invstd_out[c] = rsqrtf(var + eps);

        float denom = (count > 1) ? (float)(count - 1) : 1.0f;
        float unbiased_var = var * (float)count / denom;

        running_mean[c] = (1.0f - momentum) * running_mean[c] + momentum * m;
        running_var[c]  = (1.0f - momentum) * running_var[c]  + momentum * unbiased_var;
    } else {
        mean_out[c]   = running_mean[c];
        invstd_out[c] = rsqrtf(running_var[c] + eps);
    }
}

// ---------------------------------------------------------------------
// Kernel 3: normalize + affine transform (fused elementwise op)
// Scalar fallback version (used when vectorization is not applicable)
// ---------------------------------------------------------------------
template <typename T>
__global__ void bn_normalize_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    const float* __restrict__ mean,
    const float* __restrict__ invstd,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int C, int64_t HW, int64_t total)
{
    int64_t CHW = (int64_t)C * HW;
    // View input/output as flat (total) tensors via CuTe
    auto mX = make_tensor(make_gmem_ptr(X), make_shape(total), make_stride(Int<1>{}));
    auto mY = make_tensor(make_gmem_ptr(Y), make_shape(total), make_stride(Int<1>{}));
    for (int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
         idx < total;
         idx += (int64_t)blockDim.x * gridDim.x)
    {
        int64_t within = idx % CHW;
        int c = (int)(within / HW);
        float v = (float)mX(idx);
        float y = (v - mean[c]) * invstd[c] * weight[c] + bias[c];
        mY(idx) = (T)y;
    }
}
// ---------------------------------------------------------------------
// Kernel 3b: vectorized (float4) normalize + affine transform.
// Valid when HW is a multiple of 4 (each float4 group stays within a
// single channel) and pointers are 16B aligned. This improves memory
// throughput via wide coalesced loads/stores.
// ---------------------------------------------------------------------
__global__ void bn_normalize_kernel_vec4(
    const float4* __restrict__ X4,
    float4* __restrict__ Y4,
    const float* __restrict__ mean,
    const float* __restrict__ invstd,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int64_t CHW, int64_t HW, int64_t total4)
{
    for (int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
         idx < total4;
         idx += (int64_t)blockDim.x * gridDim.x)
    {
        int64_t elem_idx = idx * 4;
        int64_t within = elem_idx % CHW;
        int c = (int)(within / HW);
        float4 v = X4[idx];
        float m  = mean[c];
        float is = invstd[c];
        float w  = weight[c];
        float b  = bias[c];
        float4 y;
        y.x = (v.x - m) * is * w + b;
        y.y = (v.y - m) * is * w + b;
        y.z = (v.z - m) * is * w + b;
        y.w = (v.w - m) * is * w + b;
        Y4[idx] = y;
    }
}

torch::Tensor batchnorm2d_forward(torch::Tensor x,
                                   torch::Tensor weight,
                                   torch::Tensor bias,
                                   torch::Tensor running_mean,
                                   torch::Tensor running_var,
                                   bool training,
                                   double momentum,
                                   double eps)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    auto b_c = bias.contiguous();
    auto rm_c = running_mean.contiguous();
    auto rv_c = running_var.contiguous();

    int64_t N = x_c.size(0);
    int64_t C = x_c.size(1);
    int64_t H = x_c.size(2);
    int64_t W = x_c.size(3);
    int64_t HW = H * W;
    int64_t total = N * C * HW;

    auto y = torch::empty_like(x_c);

    auto opts_f32 = x_c.options().dtype(at::kFloat);
    auto mean_t   = torch::empty({C}, opts_f32);
    auto invstd_t = torch::empty({C}, opts_f32);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    if (training) {
        auto sum_t   = torch::zeros({C}, opts_f32);
        auto sumsq_t = torch::zeros({C}, opts_f32);
        int threads = 512;
        // Use multiple thread-blocks per channel so that the reduction
        // kernel can utilize many more SMs than there are channels.
        int blocks_per_channel = 8;
        dim3 grid_reduce((unsigned)(C * blocks_per_channel));
        size_t smem = 2 * threads * sizeof(float);
        bool can_vec4_reduce = (HW % 4 == 0) &&
            (reinterpret_cast<uintptr_t>(x_c.data_ptr<float>()) % 16 == 0);
        if (can_vec4_reduce) {
            int64_t HW4 = HW / 4;
            int64_t CHW4 = (int64_t)C * HW4;
            bn_reduce_kernel_vec4<<<grid_reduce, threads, smem, stream>>>(
                reinterpret_cast<const float4*>(x_c.data_ptr<float>()),
                sum_t.data_ptr<float>(),
                sumsq_t.data_ptr<float>(),
                (int)N, (int)C, HW4, CHW4, blocks_per_channel);
        } else {
            bn_reduce_kernel<float><<<grid_reduce, threads, smem, stream>>>(
                x_c.data_ptr<float>(),
                sum_t.data_ptr<float>(),
                sumsq_t.data_ptr<float>(),
                (int)N, (int)C, HW, blocks_per_channel);
        }

        int64_t count = N * HW;
        int fin_threads = 128;
        int fin_blocks = (int)((C + fin_threads - 1) / fin_threads);
        bn_finalize_kernel<<<fin_blocks, fin_threads, 0, stream>>>(
            sum_t.data_ptr<float>(),
            sumsq_t.data_ptr<float>(),
            mean_t.data_ptr<float>(),
            invstd_t.data_ptr<float>(),
            rm_c.data_ptr<float>(),
            rv_c.data_ptr<float>(),
            (int)C, count, (float)eps, (float)momentum, true);
    } else {
        int fin_threads = 128;
        int fin_blocks = (int)((C + fin_threads - 1) / fin_threads);
        bn_finalize_kernel<<<fin_blocks, fin_threads, 0, stream>>>(
            nullptr, nullptr,
            mean_t.data_ptr<float>(),
            invstd_t.data_ptr<float>(),
            rm_c.data_ptr<float>(),
            rv_c.data_ptr<float>(),
            (int)C, 0, (float)eps, (float)momentum, false);
    }

    int norm_threads = 256;
    bool can_vec4 = (HW % 4 == 0) &&
        (reinterpret_cast<uintptr_t>(x_c.data_ptr<float>()) % 16 == 0) &&
        (reinterpret_cast<uintptr_t>(y.data_ptr<float>()) % 16 == 0);
    if (can_vec4) {
        int64_t total4 = total / 4;
        int64_t blocks_needed = (total4 + norm_threads - 1) / norm_threads;
        int norm_blocks = (int)std::min<int64_t>(blocks_needed, 65535 * 8);
        if (norm_blocks < 1) norm_blocks = 1;
        bn_normalize_kernel_vec4<<<norm_blocks, norm_threads, 0, stream>>>(
            reinterpret_cast<const float4*>(x_c.data_ptr<float>()),
            reinterpret_cast<float4*>(y.data_ptr<float>()),
            mean_t.data_ptr<float>(),
            invstd_t.data_ptr<float>(),
            w_c.data_ptr<float>(),
            b_c.data_ptr<float>(),
            (int64_t)C * HW, HW, total4);
    } else {
        int64_t blocks_needed = (total + norm_threads - 1) / norm_threads;
        int norm_blocks = (int)std::min<int64_t>(blocks_needed, 65535 * 8);
        if (norm_blocks < 1) norm_blocks = 1;
        bn_normalize_kernel<float><<<norm_blocks, norm_threads, 0, stream>>>(
            x_c.data_ptr<float>(),
            y.data_ptr<float>(),
            mean_t.data_ptr<float>(),
            invstd_t.data_ptr<float>(),
            w_c.data_ptr<float>(),
            b_c.data_ptr<float>(),
            (int)C, HW, total);
    }

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "batchnorm2d kernels launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

bn_ext = load_inline(
    name="cute_batchnorm2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["batchnorm2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Batch Normalization (2D) implemented with a custom fused CuTe/CUDA kernel.
    """
    def __init__(self, num_features: int):
        super(ModelNew, self).__init__()
        self.num_features = num_features
        self.eps = 1e-5
        self.momentum = 0.1

        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))

        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
        self.register_buffer("num_batches_tracked", torch.tensor(0, dtype=torch.long))

        self._ext = bn_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.training:
            self.num_batches_tracked += 1

        return self._ext.batchnorm2d_forward(
            x,
            self.weight,
            self.bias,
            self.running_mean,
            self.running_var,
            self.training,
            self.momentum,
            self.eps,
        )

